// ORCHESTRATOR: receive, validate, create incident context (shared state)
const raw = $input.first()?.json || {};
const b = raw.body || raw;
const errors = [];
const lat = b.latitude !== undefined ? Number(b.latitude) : 20.2961;
const lng = b.longitude !== undefined ? Number(b.longitude) : 85.8245;
if (!isFinite(lat) || lat < -90 || lat > 90) errors.push('invalid latitude');
if (!isFinite(lng) || lng < -180 || lng > 180) errors.push('invalid longitude');
const cas = b.casualty_estimate !== undefined ? Number(b.casualty_estimate) : null;
if (cas !== null && (!isFinite(cas) || cas < 0)) errors.push('invalid casualty_estimate');
if (errors.length) throw new Error('ARES validation failed: ' + errors.join('; '));
const now = new Date().toISOString();
const id = 'ARES-INC-2026-' + String(Math.floor(Math.random()*9000)+1000);
const state = {
  incident_id: id,
  simulated: b.simulated !== false,
  incident_type: String(b.disaster_type || 'EARTHQUAKE').toUpperCase(),
  incident_status: 'RECEIVED',
  location: { latitude: lat, longitude: lng, address: b.location_name || 'Demo Location, Bhubaneswar, Odisha (SIMULATED)' },
  description: b.description || 'Strong tremor reported, building damage and trapped persons (SIMULATED).',
  source: b.reporter_source || 'CITIZEN_SOS',
  reported_casualties: cas,
  approval: b.approval || 'PENDING',
  approved_by: b.approved_by || null,
  agent_results: {},
  timeline: [{ t: now, event: 'INCIDENT_CREATED', by: 'ORCHESTRATOR' }],
  last_updated: now
};
return [{ json: { state } }];

const S = $('Orchestrator: Intake & Context').first().json.state;
// AGENT 01: Incident Detection (deterministic classification; not an official confirmation)
const known = ['EARTHQUAKE','FLOOD','FIRE','CYCLONE','LANDSLIDE','INDUSTRIAL_ACCIDENT','ROAD_ACCIDENT','BUILDING_COLLAPSE','HEATWAVE'];
const type = known.includes(S.incident_type) ? S.incident_type : 'OTHER';
const missing = [];
if (S.reported_casualties === null) missing.push('casualty_estimate');
if (!S.location.address) missing.push('address');
const sevMap = { EARTHQUAKE:3, FLOOD:3, CYCLONE:4, BUILDING_COLLAPSE:4, FIRE:3, LANDSLIDE:3, INDUSTRIAL_ACCIDENT:3, ROAD_ACCIDENT:2, HEATWAVE:2, OTHER:2 };
let sev = sevMap[type];
if ((S.reported_casualties||0) >= 40) sev = Math.min(5, sev+1);
const out = { agent_id:'ARES-AGENT-01', status:'COMPLETED', incident_type:type, coordinates:{lat:S.location.latitude,lng:S.location.longitude},
  detection_source:S.source, detected_at:new Date().toISOString(), initial_severity:sev, confidence:0.7,
  duplicate_candidates:[], missing_information:missing, officially_confirmed:false,
  recommended_next_steps:['Run verification','Collect '+(missing.join(', ')||'field updates')] };
S.incident_type = type; S.incident_status = 'DETECTED';
S.agent_results.detection = out;
S.timeline.push({t:out.detected_at,event:'INCIDENT_DETECTED',by:out.agent_id});
return [{json:{state:S}}];

const S = $('Agent 01: Incident Detection').first().json.state;
// AGENT 02: Verification (deterministic rules, never LLM-only)
const rel = { ERSS_112:0.9, SEISMIC_TELEMETRY:0.9, FIELD_RESPONDER:0.8, CITIZEN_SOS:0.5, 'CITIZEN_SOS_&_SEISMIC_TELEMETRY':0.8 };
const r = rel[S.source] !== undefined ? rel[S.source] : 0.4;
const evidence = [], contra = [];
let score = r*0.6;
if (isFinite(S.location.latitude)) { score += 0.15; evidence.push('coordinates present'); }
if (S.description && S.description.length > 20) { score += 0.1; evidence.push('descriptive report'); }
if (S.reported_casualties === null) contra.push('no casualty figure');
else if (S.reported_casualties > 500) contra.push('casualty figure implausibly high, needs manual check');
else { score += 0.1; evidence.push('casualty figure plausible'); }
score = Math.round(Math.min(1, score)*100)/100;
let status = 'UNVERIFIED';
if (contra.some(c=>c.includes('implausibly'))) status = 'CONFLICTING_INFORMATION';
else if (score >= 0.8) status = 'VERIFIED';
else if (score >= 0.55) status = 'PARTIALLY_VERIFIED';
const out = { agent_id:'ARES-AGENT-02', status:'COMPLETED', verification_status:status, verification_score:score,
  supporting_evidence:evidence, contradictory_evidence:contra, source_reliability:r, duplicate_reports:[],
  recommended_actions: status==='VERIFIED' ? [] : ['Human verification required before deployment'] };
S.verification_status = status; S.agent_results.verification = out;
S.timeline.push({t:new Date().toISOString(),event:'INCIDENT_VERIFIED',by:out.agent_id,detail:status});
return [{json:{state:S}}];

const S = $('Agent 02: Incident Verification').first().json.state;
// AGENT 03: Risk Assessment (facts vs estimates vs unknowns kept separate)
const sev = S.agent_results.detection.initial_severity;
const cas = S.reported_casualties;
const level = sev>=5?'CRITICAL':sev>=4?'HIGH':sev>=3?'MODERATE':'LOW';
const base = {EARTHQUAKE:1.0, FLOOD:2.0, CYCLONE:3.0, FIRE:0.5, BUILDING_COLLAPSE:0.4}[S.incident_type] || 0.8;
const mult = 1 + (sev-3)*0.25;
const zones = {
  red:{radius_km:Math.round(base*mult*10)/10, action:'cordon and evacuate'},
  amber:{radius_km:Math.round(base*mult*2*10)/10, action:'shelter-in-place / triage post'},
  green:{radius_km:Math.round(base*mult*4*10)/10, action:'staging and field hospitals'} };
const secondary = {EARTHQUAKE:['aftershocks','gas leaks','structural collapse'],FLOOD:['waterborne disease','electrocution'],FIRE:['smoke inhalation','explosion'],CYCLONE:['storm surge','flooding']}[S.incident_type] || ['unknown secondary hazards'];
const out = { agent_id:'ARES-AGENT-03', status:'COMPLETED', risk_classification:level,
  verified_facts:{ reported_casualties:cas, verification:S.verification_status },
  estimates:{ risk_zones_km:zones, affected_population: cas===null?null:cas*20 },
  predictions:{ secondary_hazards:secondary },
  unknown:[cas===null?'casualty count':null,'road closures','hospital data freshness'].filter(Boolean),
  confidence:0.6, priorities:['life safety','casualty transport','secure perimeter'] };
S.severity = level; S.risk_zones = zones; S.agent_results.risk = out; S.incident_status='ASSESSED';
S.timeline.push({t:new Date().toISOString(),event:'RISK_ASSESSED',by:out.agent_id,detail:level});
return [{json:{state:S}}];

// ORCHESTRATOR: collect parallel agent outputs, validate, resolve conflicts, synthesize plan
const S = $('Agent 03: Risk Assessment').first().json.state;
const warnings = [], conflicts = [];
function collect(name){
  try { const items = $(name).all().map(i=>i.json);
    if (items.length===1 && items[0].error) { warnings.push(name+' failed: '+(items[0].error.message||items[0].error)); return null; }
    const flat = Array.isArray(items[0]) ? items[0] : items;
    return flat.filter(x=>x && !x.error);
  } catch(e){ warnings.push(name+' unavailable: '+e.message); return null; } }
const hosp = collect('Agent 04: Hospital Source');
const amb  = collect('Agent 05: Ambulance Source');
const resc = collect('Agent 06: Rescue Source');
const medArr = (()=>{ try { const m=$('Agent 07: Medical Source').first().json; return m&&!m.error?m:null; } catch(e){ return null; } })();
const shel = collect('Agent 10: Shelter Source');
const lat=S.location.latitude, lng=S.location.longitude;
const R=6371, rad=x=>x*Math.PI/180;
const hav=(a,b,c,d)=>{const dl=rad(c-a),dn=rad(d-b);const h=Math.sin(dl/2)**2+Math.cos(rad(a))*Math.cos(rad(c))*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.sqrt(h));};
const crit = [];
// AGENT 04 hospital ranking (deterministic scoring)
let hospital_plan = [];
if (hosp && hosp.length){
  const ranked = hosp.map(h=>{
    const hl=h.lat??h.latitude, hn=h.lng??h.longitude;
    const d = (hl!=null&&hn!=null)? hav(lat,lng,hl,hn) : (h.distance_km ?? null);
    const beds = h.available_beds, icu = h.icu_available;
    const score = (d==null?0:Math.max(0,1-d/30))*0.4 + (beds==null?0:Math.min(1,beds/50))*0.3 + (icu==null?0:Math.min(1,icu/10))*0.2 + ((h.trauma_level||3)<=2?0.1:0);
    return { hospital_id:h.id, name:h.name, distance_km:d==null?null:Math.round(d*10)/10, available_beds:beds??'UNKNOWN', icu_available:icu??'UNKNOWN', trauma_level:h.trauma_level??'UNKNOWN', score:Math.round(score*100)/100, data_note:'verify capacity with hospital before routing' };
  }).sort((a,b)=>b.score-a.score);
  hospital_plan = ranked.slice(0,5);
} else { crit.push('hospital_allocation'); warnings.push('No hospital data: hospital plan INCOMPLETE'); }
// AGENT 05 ambulances: no duplicate assignment, proposals only
let ambulance_plan = [];
if (amb && amb.length){
  const used = new Set();
  const need = S.reported_casualties===null ? 2 : Math.max(2, Math.ceil(S.reported_casualties/2));
  const list = amb.filter(a=>a.status==='AVAILABLE'||!a.status).map(a=>({a, d:(a.current_lat!=null&&a.current_lng!=null)?hav(lat,lng,a.current_lat,a.current_lng):9999})).sort((x,y)=>x.d-y.d);
  for (const {a,d} of list){ if (ambulance_plan.length>=need) break; if (used.has(a.id||a.vehicle_number)) continue; used.add(a.id||a.vehicle_number);
    const h = hospital_plan.length ? hospital_plan[ambulance_plan.length % Math.min(hospital_plan.length,3)] : null;
    ambulance_plan.push({ ambulance_id:a.id, vehicle:a.vehicle_number, type:a.ambulance_type, distance_km: d===9999?null:Math.round(d*10)/10, proposed_destination: h?h.name:'UNASSIGNED', requires_dispatcher_approval:true }); }
  if (ambulance_plan.length < need) warnings.push('Only '+ambulance_plan.length+' of '+need+' ambulances available: shortage');
} else { crit.push('ambulance_dispatch'); warnings.push('No ambulance data: ambulance plan INCOMPLETE'); }
// AGENT 06 rescue
const rescue_plan = (resc||[]).slice(0,4).map(t=>({team_id:t.id,name:t.name,type:t.type,members:t.members_count??'UNKNOWN',skills:t.skills||[],note:'simulated resource, no real agency availability assumed',requires_approval:true}));
if (!resc||!resc.length) { warnings.push('No rescue team data'); }
// AGENT 07 medical supply (reviewed protocol from backend; else flagged static rule)
const n = S.reported_casualties===null ? null : S.reported_casualties;
let medical_supply_plan;
if (medArr) medical_supply_plan = { source:'backend /medical/requirements (reviewed protocol)', data:medArr, assumptions:['casualty estimate '+(n===null?'UNKNOWN':n)] };
else { medical_supply_plan = { source:'UNAVAILABLE', data:null, assumptions:[] }; warnings.push('Medical protocol service unavailable: supply plan INCOMPLETE'); }
// AGENT 08 routes (straight line only as UNVERIFIED indicative; real road routing needs OSRM)
const route_plan = ambulance_plan.slice(0,3).map(a=>{ const h=hospital_plan.find(x=>x.name===a.proposed_destination);
  return { from:'incident', to:a.proposed_destination, distance_km:h?h.distance_km:null, eta_min:null, verified:false, note:'UNVERIFIED: no road-network routing; do not use for ETA' }; });
if (route_plan.length) warnings.push('Routes are UNVERIFIED (no OSRM/GraphHopper connected)');
// AGENT 10 shelters
const shelter_plan = (shel||[]).map(s=>({name:s.name,capacity:s.capacity,occupancy:s.current_occupancy,headroom:(s.capacity!=null&&s.current_occupancy!=null)?s.capacity-s.current_occupancy:'UNKNOWN',requires_approval:true})).slice(0,3);
// conflict detection
const ids = ambulance_plan.map(a=>a.ambulance_id); if (new Set(ids).size!==ids.length) conflicts.push('duplicate ambulance assignment');
if (hospital_plan.length && hospital_plan.every(h=>h.available_beds==='UNKNOWN')) conflicts.push('all hospital capacity UNKNOWN');
// AGENT 09 communications (SIMULATED only)
const mk=(type,to,subject,body)=>({type,recipient:to,priority:'HIGH',incident_id:S.incident_id,subject,body,delivery_status:'SIMULATED_NOT_SENT',approval_required:true,timestamp:new Date().toISOString()});
const summaryLine = S.incident_type+' at '+S.location.address+' | risk '+S.severity+' | verification '+S.verification_status;
const communication_plan = [
  mk('INCIDENT_ALERT','District Control Room','SIMULATED: '+S.incident_type,summaryLine),
  mk('HOSPITAL_REQUEST', hospital_plan[0]?hospital_plan[0].name:'Hospitals','SIMULATED: surge readiness','Prepare for casualties. Confirm bed and ICU availability. '+summaryLine),
  mk('RESCUE_REQUEST','Rescue teams','SIMULATED: tasking proposal',summaryLine)
];
// priorities and status
const priorities = S.agent_results.risk.priorities;
const incomplete = crit.length>0;
const plan = { incident_id:S.incident_id, simulated:S.simulated,
  response_summary: summaryLine + (incomplete?' | PLAN INCOMPLETE: '+crit.join(', '):''),
  priorities, hospital_plan, ambulance_plan, rescue_plan, medical_supply_plan, route_plan, shelter_plan, communication_plan,
  conflicts, warnings, plan_incomplete:incomplete, missing_agents:crit, approval_required:true, plan_status:'PENDING_APPROVAL' };
S.response_plan = plan; S.incident_status='RESPONSE_PLANNED';
S.timeline.push({t:new Date().toISOString(),event:'RESPONSE_PLAN_CREATED',by:'ORCHESTRATOR'});
return [{json:{state:S}}];

// HUMAN APPROVAL GATE + AUTHORIZED (SIMULATED) DEPLOYMENT + REPORT (Agent 11) + MONITORING SEED (Agent 12)
const S = $('Orchestrator: Plan Synthesis').first().json.state;
const plan = S.response_plan; const now = new Date().toISOString();
const report = (kind)=>({ report_type:kind, incident_id:S.incident_id, generated_at:now, simulated:S.simulated,
  verified_information:{ verification:S.verification_status, reported_casualties:S.reported_casualties },
  estimates:S.agent_results.risk.estimates,
  response_status:plan.plan_status, hospitals_proposed:plan.hospital_plan.map(h=>h.name),
  ambulances_proposed:plan.ambulance_plan.length, rescue_teams_proposed:plan.rescue_plan.length,
  pending_tasks:['Confirm hospital capacity','Verify routes with road-network routing','Human sign-off'],
  operational_challenges:plan.warnings, recommendations:plan.priorities });
const approved = S.approval === 'APPROVED' && S.approved_by;
if (S.approval === 'APPROVED' && !S.approved_by) plan.warnings.push('APPROVED ignored: approved_by is required for audit');
if (plan.plan_incomplete && approved) plan.warnings.push('Approving an INCOMPLETE plan: missing '+plan.missing_agents.join(', '));
let result;
if (!approved) {
  plan.plan_status = 'PENDING_APPROVAL';
  S.timeline.push({t:now,event:'AWAITING_APPROVAL',by:'ORCHESTRATOR'});
  result = { stage:'AWAITING_HUMAN_APPROVAL', how_to_approve:'Re-POST the same payload with {"approval":"APPROVED","approved_by":"<officer name>"}', report:report('Initial Situation Report') };
} else {
  plan.plan_status = 'APPROVED_DEPLOYED_SIMULATED';
  S.timeline.push({t:now,event:'APPROVAL_GRANTED',by:S.approved_by});
  S.timeline.push({t:now,event:'SIMULATED_DEPLOYMENT',by:'ORCHESTRATOR'});
  const monitoring = { agent_id:'ARES-AGENT-12', mode:'event_driven', watch:['HOSPITAL_CAPACITY_CHANGED','ROAD_CLOSED','AMBULANCE_AVAILABLE','SEVERITY_CHANGED','NEW_HAZARD_DETECTED'], note:'Reassessment runs only for agents affected by an event, via the ares-event webhook' };
  const deployment = { delivery:'SIMULATED, no real calls, SMS or dispatch performed', ambulance_orders:plan.ambulance_plan.map(a=>({vehicle:a.vehicle,destination:a.proposed_destination,status:'ASSIGNED_SIMULATED'})), messages:plan.communication_plan.map(m=>({...m,delivery_status:'SIMULATED_DELIVERED'})) };
  result = { stage:'DEPLOYED_SIMULATED', deployment, monitoring, report:report('Emergency Status Report') };
}
S.last_updated = now;
return [{json:{success:true,mode:'ARES_N8N_MULTI_AGENT',incident_id:S.incident_id,result,response_plan:plan,shared_state:{incident_status:S.incident_status,severity:S.severity,verification_status:S.verification_status,timeline:S.timeline,agent_results:S.agent_results}}}];

// EVENT-DRIVEN REASSESSMENT (Agent 12): map event -> only the agents that must re-run
const b = $input.first().json.body || $input.first().json;
const map = { HOSPITAL_CAPACITY_CHANGED:['ARES-AGENT-04','ARES-AGENT-08','ARES-AGENT-09'], ROAD_CLOSED:['ARES-AGENT-08','ARES-AGENT-05'], AMBULANCE_AVAILABLE:['ARES-AGENT-05'], SEVERITY_CHANGED:['ARES-AGENT-03','ARES-AGENT-04','ARES-AGENT-05','ARES-AGENT-06','ARES-AGENT-07','ARES-AGENT-10','ARES-AGENT-11'], NEW_HAZARD_DETECTED:['ARES-AGENT-03','ARES-AGENT-06','ARES-AGENT-10'], SUPPLY_SHORTAGE:['ARES-AGENT-07'], RESCUE_TEAM_DEPLOYED:['ARES-AGENT-06','ARES-AGENT-11'] };
const ev = String(b.event||'').toUpperCase();
if (!map[ev]) return [{json:{success:false,error:'Unknown event',supported:Object.keys(map)}}];
return [{json:{success:true,incident_id:b.incident_id||null,event:ev,agents_to_rerun:map[ev],action:'Re-POST the incident to /webhook/ares-emergency with updated fields; only listed agents need fresh data',not_restarted:'all other agents keep prior outputs'}}];
